/**
 * Error helpers.
 *
 * The public contract deliberately uses plain `Error` objects (not a custom
 * subclass). A stable, enumerable code is attached so consumers can branch on
 * failures without depending on engine-specific error shapes.
 */

/** Stable error categories. Values are part of the public contract. */
export const PLAYER_ERROR_CODES = [
  "invalid-argument",
  "invalid-state",
  "unsupported-source",
  "unsupported-environment",
  "network-error",
  "media-error",
  "aborted",
  "destroyed",
  "not-implemented",
] as const;

export type PlayerErrorCode = (typeof PLAYER_ERROR_CODES)[number];

export interface PlayerErrorOptions {
  readonly code: PlayerErrorCode;
  readonly cause?: unknown;
  readonly details?: Readonly<Record<string, unknown>>;
}

/** A plain `Error` carrying a stable code and optional structured details. */
export type PlayerError = Error & {
  readonly code: PlayerErrorCode;
  readonly details: Readonly<Record<string, unknown>>;
};

/** Creates a plain `Error` with a stable `code` and optional `details`. */
export function createPlayerError(message: string, options: PlayerErrorOptions): PlayerError {
  const error = new Error(
    message,
    options.cause === undefined ? undefined : { cause: options.cause },
  ) as PlayerError;

  Object.defineProperty(error, "name", {
    configurable: true,
    value: "UniversalPlayerError",
    writable: true,
  });
  Object.defineProperty(error, "code", {
    configurable: true,
    enumerable: true,
    value: options.code,
    writable: false,
  });
  Object.defineProperty(error, "details", {
    configurable: true,
    enumerable: true,
    value: options.details === undefined ? {} : { ...options.details },
    writable: false,
  });

  return error;
}

/** Returns true when a value is a {@link PlayerError}. */
export function isPlayerError(value: unknown): value is PlayerError {
  return (
    value instanceof Error &&
    typeof (value as Partial<PlayerError>).code === "string" &&
    (PLAYER_ERROR_CODES as readonly string[]).includes((value as PlayerError).code)
  );
}

/** Normalizes any thrown value into a {@link PlayerError}. */
export function toPlayerError(
  value: unknown,
  fallbackCode: PlayerErrorCode = "media-error",
): PlayerError {
  if (isPlayerError(value)) {
    return value;
  }

  if (value instanceof Error) {
    return createPlayerError(value.message, { code: fallbackCode, cause: value });
  }

  return createPlayerError(String(value), { code: fallbackCode, cause: value });
}
